{"code":"import json, numpy as np
with open('evaluations.json') as f:
    evals = json.load(f)

ings = ["pea protein", "coconut oil", "sunflower oil", "potato starch", "fava bean protein", "methylcellulose", "yeast extract", "onion", "white pepper"]
r5 = {x['ingredient']: x['fraction'] for x in evals[4]['recipe']}
v5 = np.array([r5[k] for k in ings])

rows = []
for e in evals:
    r = {x['ingredient']: x['fraction'] for x in e['recipe']}
    if set(r.keys()) == set(ings):
        v = np.array([r[k] for k in ings])
        l2 = np.linalg.norm(v - v5)
        l1 = np.sum(np.abs(v - v5))
        rows.append((l2, l1, e['iteration'], e['target_dissimilarity'], v - v5))

for l2, l1, it, y, d in sorted(rows):
    print(f"Iter {it:2d}: L2={l2:.5f}, L1={l1:.4f} -> y={y:.6f} | d={np.round(d, 3)}")
"}
